import json,os
from playwright.sync_api import sync_playwright
raw=os.environ['HONRO_CLEAR_EXPORT'];stage=int(os.environ['HONRO_RESUME_STAGE']);cleared=str(stage-1);expected=json.loads(open(raw).read())
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);p=b.new_page(viewport={'width':1440,'height':900});err=[];p.on('pageerror',lambda e:err.append(str(e)));p.goto('http://127.0.0.1:8770/HONRO.html');p.wait_for_function('window.HonroApp && window.HonroCampaignLoader');p.evaluate('''async n=>await HonroCampaignLoader.ensureStage(n)''',stage);p.locator('#file-import').set_input_files(raw);p.wait_for_timeout(2500);loaded=p.evaluate('''()=>({stage:HonroApp.profile?.honroBattle?.honroStage,clear:HonroApp.profile?.cleared?.[String(HonroApp.profile.honroBattle.honroStage-1)],size:localStorage.getItem('honro-first-act-profile-1')?.length,locked:HonroApp.profileStore.locked})''');assert loaded['stage']==stage and loaded['clear']==expected['cleared'][cleared] and not loaded['locked'];print('import',loaded,flush=True);p.reload();p.wait_for_function('window.HonroApp');p.get_by_text('이어서 걷기',exact=True).click();p.wait_for_function('(n)=>HonroApp.engine?.b?.honroStage===n',arg=stage,timeout=30000);p.wait_for_timeout(1500);resumed=p.evaluate('''()=>({stage:HonroApp.engine.b.honroStage,round:HonroApp.engine.b.round,enemies:HonroApp.engine.b.units.filter(u=>u.side===1&&!u.dead).length,clear:HonroApp.profile.cleared[String(HonroApp.engine.b.honroStage-1)],heroes:Object.fromEntries(Object.entries(HonroApp.profile.heroes).map(([k,v])=>[k,v.xp]))})''');assert resumed['stage']==stage and resumed['clear']==expected['cleared'][cleared] and resumed['heroes']=={k:v.get('xp') for k,v in expected['heroes'].items()} and not err;print('resume',resumed,'errors',err,flush=True);p.screenshot(path=os.environ.get('HONRO_RELOAD_SCREENSHOT','/tmp/honro-import-reload.png'));b.close()
